fn save(m:&Model<'_>,b:&Binding,f:Frame,s:Option<movement::Step>,out:&Path,images:&mut Vec<Value>,rows:&mut Vec<Value>,moves:&mut Vec<Value>,held:&mut Option<Frame>){if let Some(old)=held.take(){assert!(old.view(&m.scene,b,b.observed).is_err());}images.push(fixture::png(&out.join(format!("{:02}-{}-{}.png",images.len(),f.clock,f.kind.replace(|c:char|!c.is_ascii_alphanumeric(),"_"))),f.view(&m.scene,b,b.observed).unwrap().rgba(),1024,768));rows.push(json!({"clock":f.clock,"kind":f.kind,"player":f.player_frame,"fire":f.fire_frame,"RGBA_sha256":images.last().unwrap()["RGBA_sha256"]}));if let Some(s)=s{moves.push(json!({"clock":s.at,"action":s.action,"frame":s.frame,"bank":s.bank,"sub":s.sub,"cell":[s.cell.x,s.cell.y],"committed":s.cell_committed,"move64bbc3":s.active_move,"prequeued":s.added.iter().map(|t|t.at).collect::<Vec<_>>(),"camera_center":[s.camera.center.x,s.camera.center.y],"camera_offset":[s.camera.offset.x,s.camera.offset.y],"raw_catalog_events_not_executed":String::from_utf8(s.raw_events).unwrap()}));}*held=Some(f);}
